import singleton from "./DataSingleton.js";
const EventEmitter = require("eventemitter3");
// import * as ml5 from "ml5";
//import p5 from 'p5';
import ml5 from "ml5";

class MovingAverage {
  constructor(windowSize) {
    this.windowSize = windowSize;
    this.values = [];
  }

  next(value) {

    this.values.push(parseFloat(value));
    if (this.values.length > this.windowSize) {
      this.values.shift(); // remove oldest
    }
    const sum = this.values.reduce((acc, val) => acc + val, 0);

    return sum / this.values.length;
  }
}

export default function sketch(p) {
  const videoSize = {
    width: 960,
    height: 480,
  };
  const resizedSize = {
    width: 224, // Adjusted for MobileNet
    height: 224, // Adjusted for MobileNet
  };
  let video;
  let mobilenetClassifier;
  let label;
  let confidence;
  let offscreenGraphics;
  let aspectRatio;
  let color1;
  let color2;
  let confidenceSmooth = new MovingAverage(8);
  const jsSketchEvent = new EventEmitter();

  p.setup = () => {
    const myCanvas = p.createCanvas(videoSize.width, videoSize.height);
    myCanvas.parent("canvas-container");
    //   myCanvas.hide();
    // Specify camera constraints
    const constraints = {
      video: {
        facingMode: "environment", // Attempt to use the rear camera
      },
      audio: false,
    };
    video = p.createCapture(constraints, () => {
      aspectRatio = video.width / video.height;
    });
    // video.size(videoSize.width, videoSize.width / aspectRatio);
    video.hide(); // Ensure the original video feed is not displayed

    //automatiically resize canvas once video loads up
    video.elt.onloadedmetadata = () => {
      p.adjustCanvasSize();
    };

    // Create an off-screen graphics buffer for the resized frame
    offscreenGraphics = p.createGraphics(resizedSize.width, resizedSize.height);

    // Load the MobileNet model
    mobilenetClassifier = ml5.imageClassifier("MobileNet", p.modelReady);

    // Create placeholders for label and confidence
    // labelDiv = p.createDiv("Label: ");
    // confidenceDiv = p.createDiv("Confidence: ");

    // Set up a function to continuously classify video frames
    p.classifyVideo();
    p.textSize(32);
    p.textFont("Montserrat");
    p.textAlign(p.CENTER, p.CENTER);
    color1 = p.color("#FBBE9F"); // light grayish red
    color2 = p.color("#008E7D");
  };

  p.modelReady = () => {
    console.log("Model Loaded!");
  };

  p.classifyVideo = () => {
    // Capture a frame from the video
    //p.image(video, 0, 0, videoSize.width, videoSize.height);

    // Resize the frame to MobileNet's expected dimensions
    offscreenGraphics.image(video, 0, 0, resizedSize.width, resizedSize.height);

    // Classify the processed frame using MobileNet
    mobilenetClassifier.classify(offscreenGraphics, p.gotResult);
  };

  p.gotResult = (error, results) => {
    if (error) {
      console.error(error);
      return;
    }

    // put data in singleton
    singleton.setLabel(results[0]);
    // singleton.confidence = results[0].confidence;
    // Update the content of the existing div elements
    label = results[0].label;
    confidence = p.nf(results[0].confidence, 0, 2);

    // Continue classification
    p.classifyVideo();
  };

  p.draw = () => {
    let textSizePercentage = 0.05; // Adjust this value to set the text size as a percentage of window width
    let dynamicTextSize = p.width * textSizePercentage;
    // Display the processed video frame on the canvas

    p.textSize(dynamicTextSize);
    p.image(video, 0, 0, p.width, p.width / aspectRatio);
    p.strokeWeight(0);
    p.fill("#4C3D3880");
    p.rect(0, 0, p.width, (p.width / aspectRatio) * 0.1);
    p.fill("#4C3D3880");
    p.rect(0, (p.width / aspectRatio) * 0.87, p.width, p.width / aspectRatio);
    p.fill("#FFEA82");

    p.text("Aurascope", p.width / 2, (p.width / aspectRatio) * 0.05);
    p.fill("#FFFFFF");
    p.textSize(dynamicTextSize*0.4)
    p.text("Designed and developed by Aeroidio (https://www.aeroid.io)", p.width / 2, (p.width / aspectRatio) * 0.98)
    p.fill(p.lerpColor(color1, color2, confidence));
    p.textSize(
      p.map(confidence, 0, 1, dynamicTextSize * 0.5, dynamicTextSize * 1.25),
    );
    p.strokeWeight(0.5);
    p.stroke(255)
    p.text(label, p.width / 2, (p.width / aspectRatio) * 0.92);


    let confidenceStretch = p.width/2 * confidenceSmooth.next(confidence);

    p.fill(p.lerpColor(color1, color2, confidence));
    // p.fill("FFF")
    p.strokeWeight(1);
    p.stroke(255)
    p.rect((p.width/2)-confidenceStretch, (p.width / aspectRatio) * 0.86, confidenceStretch*2, 10)
    // console.log(p.width, (p.width/2)-confidenceStretch, (p.width/2)+confidenceStretch)
  };

  p.windowResized = () => {
    p.adjustCanvasSize();
  };

  p.adjustCanvasSize = () => {
    let newWidth = p.windowWidth;
    let newHeight = p.windowWidth / aspectRatio;

    // Adjust height based on window height if too tall
    if (newHeight > p.windowHeight) {
      newHeight = p.windowHeight;
      newWidth = p.windowHeight * aspectRatio;
    }
    p.resizeCanvas(newWidth, newHeight);
  };
}
