// Import required modules
import singleton from "./DataSingleton.js";

import sketch from "./sketch.js";
import eventMapping from "./EventMapping";
import { rnboPatch } from "./rnboPatch";

const { createDevice, TimeNow, MessageEvent } = require("@rnbo/js");
const EventEmitter = require("events");
const p5 = require("p5");
let maxAccelMag = 0;
let maxRotationMag = 0;
let device;

/**
 * Convert amplitude from decibel to linear scale
 * @param dB : number in decibels
 */
const dBtoA = function (dB) {
  return 10 ** (dB / 20);
};

// Create Audio Context
let WAContext = window.AudioContext || window.webkitAudioContext;
let context = new WAContext();

// Create a gain node for controlling the overall volume of the audio context
const gainNode = context.createGain();
gainNode.gain.value = dBtoA(0.0); // The initial gain (volume) is set to three decibels below maximum

/**
 * Asynchronously sets up the variable environment.
 * @async
 * @function setup
 */
const setup = async () => {
  let patcher = rnboPatch;
  device = await createDevice({ context, patcher });
  const eventEmitter = new EventEmitter();

  const accelRNBO = device.parametersById.get("acceleration");
  const rotRNBO = device.parametersById.get("rotation");
  const suddenRNBO = device.parametersById.get("sudden");
  // const volRNBO = device.parametersById.get("volume");
  // volRNBO.value = 0.0;

  // Event listener for changes in the label
  singleton.eventEmitter.on("labelChanged", (value) => {
    let valueArray = value.label.split(",");
    let confidence = value.confidence;
    if (typeof valueArray == "string") {
      valueArray = [valueArray];
    }

    let label = valueArray.shift();
    if (eventMapping[label] !== undefined) {
      let labelNum = eventMapping[label];

      if (!isNaN(labelNum)) {
        const event = new MessageEvent(TimeNow, "in2", [labelNum, confidence]);
        device.scheduleEvent(event);
      }
    }
  });

  // Event listener for updates in time
  singleton.eventEmitter.on("updateTime", (section) => {
    //JUST SECTION 1 for right now NEED TO UPDATE payload to send section
    const event = new MessageEvent(TimeNow, "in1", [section]);
    device.scheduleEvent(event);
    console.log("section updater");
  });

  // Event listener for changes in motionData
  singleton.eventEmitter.on("accelerationMagnitude", (accelMag) => {
    accelRNBO.value = accelMag;
  });

  singleton.eventEmitter.on("rotationMagnitude", (rotMag) => {
    rotRNBO.value = rotMag;
  });

  singleton.eventEmitter.on("suddenMovementDetected", () => {
    // let suddenText = document.getElementById("sudden");

    suddenRNBO.value = 1;
    setTimeout(() => {
      suddenRNBO.value = 0;
    }, 100);
  });

  //print RNBO outports to the console
  device.messageEvent.subscribe((ev) => {
    // console.log(`Received message ${ev.tag}: ${ev.payload}`);
  });

  device.node.connect(gainNode);
  gainNode.connect(context.destination);

  // document.getElementById("section").addEventListener("change", function () {
  //   const event = new MessageEvent(TimeNow, "in1", [parseInt(this.value)]);
  //   device.scheduleEvent(event);
  // });
};
document.getElementById("overlay").addEventListener("click", function () {
  if (typeof DeviceMotionEvent.requestPermission === "function") {
    DeviceMotionEvent.requestPermission()
      .then((permissionState) => {
        if (permissionState === "granted") {
          console.log("permission granted");
        }
      })
      .catch(console.error);
  }
  this.style.display = "none";
  setup()
    .then(new p5(sketch))
    .then(context.resume())
    .then(() => {
      let start_section = singleton.determineSection();
      const event = new MessageEvent(TimeNow, "in1", [start_section]);
      device.scheduleEvent(event);
    });
});
