const EventEmitter = require("eventemitter3");
class DataSingleton {
  constructor() {
    this.label = "Singleton Data";
    this.confidence = 0.0;
    this.eventEmitter = new EventEmitter();
    this.minutes = -1;
    this.CYCLEDURATION = 60 / 10; //15 sections in one hour
    this.SECTIONDURATION = this.CYCLEDURATION / 3; //3 sections in one cycle ,,,,, each section 1.33333.... minutes
    // Bind the updateTime method to the instance to maintain the correct 'this' context
    this.updateTime = this.updateTime.bind(this);
    this.clock = setInterval(this.updateTime, 1000);
    this.section = 0;
    this.motionData = {
      acceleration: null,
      accelerationIncludingGravity: null,
      rotationRate: null,
    };
    // Bind the updateMotionData method to the instance to maintain the correct 'this' context
    this.updateMotionData = this.updateMotionData.bind(this);
    window.addEventListener("devicemotion", this.updateMotionData);
  }
  // Callback for handling device motion events
  updateMotionData(event) {
    console.log("updateMotionData called");
    // Update motion data
    this.motionData.acceleration = event.acceleration;
    this.motionData.accelerationIncludingGravity =
      event.accelerationIncludingGravity;
    this.motionData.rotationRate = event.rotationRate;

    // Calculate acceleration magnitude
    const accelerationMagnitude = this.calculateAccelerationMagnitude(
      this.motionData.acceleration,
    );

    // Calculate rotation magnitude
    const rotationMagnitude = this.calculateRotationMagnitude(
      this.motionData.rotationRate,
    );

    // Compare to threshold (adjust threshold value as needed)
    const threshold = 20; // Adjust this threshold value as needed
    if (accelerationMagnitude > threshold) {
      // A sudden movement is detected, trigger your action here
      this.eventEmitter.emit("suddenMovementDetected");
      console.log("sudden event");
    }

    // Emit an event to notify other parts of the application
    this.eventEmitter.emit("accelerationMagnitude", accelerationMagnitude);
    this.eventEmitter.emit("rotationMagnitude", rotationMagnitude);
  }

  // Get the current motion data
  getMotionData() {
    return this.motionData;
  }

  // Add event listener to react to changes in motion data

  setLabel(value) {
    if (value !== this.label) {
      this.label = value;
      // Emit an event when the property changes
      this.eventEmitter.emit("labelChanged", value);
    }
  }

  /**
   *
   * @returns {number} section number calculated from hour minutes, CYCLEDURATION, and SECTION DURATION
   */
  determineSection() {
    return (
      Math.floor((this.minutes % this.CYCLEDURATION) / this.SECTIONDURATION) + 1
    );
  }
  updateTime() {
    let current_time = new Date();
    let current_minutes = current_time.getMinutes();
    if (this.minutes !== current_minutes) {
      this.minutes = current_minutes;
      let section = this.determineSection();
      // console.log(`current min: ${this.minutes}`)
      if (section !== this.section) {
        this.section = section;
        this.eventEmitter.emit("updateTime", section);
      }
    }
  }
  calculateAccelerationMagnitude(acceleration) {
    return Math.sqrt(
      acceleration.x ** 2 + acceleration.y ** 2 + acceleration.z ** 2,
    );
  }
  calculateRotationMagnitude(rotation) {
    return Math.sqrt(
      rotation.alpha ** 2 + rotation.beta ** 2 + rotation.gamma ** 2,
    );
  }
}

const instance = new DataSingleton();
// Object.freeze(instance);

export default instance;
